html:
{% if doc.docstatus == 1 %}
{# ==============================
   EXPENSES (MATCH PDF LAYOUT)
   - Uses Letterhead ({{ letter_head }})
   - Table: SR / Expense Type / Expense Account / Amount / Remark
   - Dynamic workflow users:
       prepared_by_user
       expense_approver_user
       finance_user
       director_user

   FALLBACK RULES
   - Prepared By  -> Bahja Abdinasir Abdilkadir
   - Reviewed By  -> Hassan Mukhtar Yahye
   - Checked By   -> show only if finance user exists
   - Approved By  -> Dr. Abdifetah Ibrahim Omar
================================ #}

{# helper: format full name from user #}
{% macro user_fullname(user_id) -%}
  {%- if user_id -%}
    {{ frappe.db.get_value("User", user_id, "full_name") or user_id }}
  {%- else -%}

  {%- endif -%}
{%- endmacro %}

{# helper: format number like 2,158.00 #}
{% macro fmt_num(val) -%}
  {{ "{:,.2f}".format(frappe.utils.flt(val or 0)) }}
{%- endmacro %}

{# dynamic users #}
{% set prepared_user = doc.prepared_by_user or doc.owner %}
{% set expense_approver_user = doc.expense_approver_user %}
{% set finance_user = doc.finance_user %}
{% set director_user = doc.director_user %}

{# final display names with fallback #}
{% set prepared_name = user_fullname(prepared_user)|trim or "Bahja Abdinasir Abdilkadir" %}
{% set expense_approver_name = user_fullname(expense_approver_user)|trim or "0" %}
{% set finance_name = user_fullname(finance_user)|trim %}
{% set director_name = user_fullname(director_user)|trim or "Hassan Mukhtar Yahye" %}

<style>
  .ex-wrap{
    font-family: "Segoe UI", Tahoma, Arial, sans-serif;
    font-size: 12.5px;
    color:#1f2d3d;
  }

  .page{
    page-break-inside: avoid;
  }

  .ex-title{
    display:flex;
    justify-content: space-between;
    align-items: flex-end;
    margin: 8px 0 10px 0;
  }
  .ex-title h2{
    margin:0;
    font-size: 20px;
    letter-spacing: .6px;
    text-transform: uppercase;
  }
  .ex-ref{
    text-align:right;
    font-size: 11px;
    color:#6c757d;
    line-height: 1.4;
  }
  .ex-divider{
    border:0;
    border-top:1px solid #212529;
    margin: 10px 0 12px 0;
    opacity:.8;
  }

  .ex-grid{
    width:100%;
    border-collapse: collapse;
    table-layout: fixed;
    margin-bottom: 10px;
  }
  .ex-grid td{
    padding: 6px 8px;
    vertical-align: top;
  }
  .ex-l{
    font-weight: 800;
    color:#212529;
    width: 18%;
    white-space: nowrap;
  }
  .ex-v{
    width: 32%;
    word-wrap: break-word;
  }

  .ex-table{
    width:100%;
    border-collapse: collapse;
    table-layout: fixed;
    margin-top: 8px;
  }
  .ex-table th, .ex-table td{
    border: 1px solid #2f343a;
    padding: 7px 8px;
    vertical-align: top;
  }
  .ex-table th{
    font-weight: 900;
    text-transform: uppercase;
    font-size: 11px;
    color:#212529;
  }

  .col-sr  { width: 6%;  text-align:center; }
  .col-type{ width: 22%; }
  .col-acc { width: 32%; }
  .col-amt { width: 12%; text-align:right; font-variant-numeric: tabular-nums; white-space:nowrap; }
  .col-rem { width: 28%; }

  .ex-remark{
    white-space: pre-wrap;
    word-break: break-word;
    line-height: 1.35;
  }

  .ex-totals{
    margin-top: 12px;
    border: 1px solid #e9ecef;
    border-radius: 8px;
    padding: 10px 12px;
    background: #fbfcfd;
  }
  .ex-totals table{
    width:100%;
    border-collapse: collapse;
  }
  .ex-totals td{
    padding: 6px 2px;
  }
  .ex-totals .k{
    font-weight: 900;
    color:#212529;
    width: 55%;
  }
  .ex-totals .v{
    text-align:right;
    font-weight: 900;
    font-variant-numeric: tabular-nums;
    width: 45%;
    white-space: nowrap;
  }

  .ex-sign-row{
    margin-top: 42px;
    display:flex;
    justify-content: space-between;
    gap: 14px;
  }
  .ex-sign-box{
    flex: 1;
    text-align:center;
  }
  .ex-sign-line{
    margin-top: 50px;
    border-top: 2px dashed #2f343a;
    padding-top: 6px;
    font-weight: 900;
    font-size: 12px;
  }
  .ex-sign-meta{
    margin-top: 4px;
    font-size: 11px;
    color:#212529;
    font-weight: 700;
    min-height: 30px;
    line-height: 1.35;
    word-break: break-word;
  }
  .ex-footer{
    margin-top: 18px;
    border-top: 1px solid #e9ecef;
    padding-top: 8px;
    text-align:center;
    font-size: 10.5px;
    color:#6c757d;
  }
</style>

<div class="ex-wrap">
  {{ letter_head }}

  <div class="page">
    <div class="ex-title">
      <h2>Expenses</h2>
      <div class="ex-ref">
        <div><b>{{ doc.name }}</b></div>
        {% if doc.naming_series %}<div>Series: {{ doc.naming_series }}</div>{% endif %}
        {% if doc.workflow_state %}<div>Workflow: {{ doc.workflow_state }}</div>{% endif %}
      </div>
    </div>

    <hr class="ex-divider">

    <table class="ex-grid">
      <tr>
        <td class="ex-l">Company</td>
        <td class="ex-v">{{ doc.company or "-" }}</td>

        <td class="ex-l">Posting Date</td>
        <td class="ex-v">{{ doc.posting_date or "-" }}</td>
      </tr>
      <tr>
        <td class="ex-l">Paid From</td>
        <td class="ex-v" colspan="3">{{ doc.paid_from or "-" }}</td>
      </tr>
    </table>

    <table class="ex-table">
      <thead>
        <tr>
          <th class="col-sr">SR</th>
          <th class="col-type">Expense Type</th>
          <th class="col-acc">Expense Account</th>
          <th class="col-amt">Amount</th>
          <th class="col-rem">Remark</th>
        </tr>
      </thead>
      <tbody>
        {% set rows = doc.expense_lines or [] %}
        {% if rows and rows|length %}
          {% for r in rows %}
            <tr>
              <td class="col-sr">{{ loop.index }}</td>
              <td class="col-type">{{ r.expense_type or "-" }}</td>
              <td class="col-acc">{{ r.expense_account or "-" }}</td>
              <td class="col-amt">{{ fmt_num(r.amount) }}</td>
              <td class="col-rem"><div class="ex-remark">{{ r.line_remark or "-" }}</div></td>
            </tr>
          {% endfor %}
        {% else %}
          <tr>
            <td colspan="5" style="text-align:center; padding: 14px; color:#6c757d;">
              No expense lines found.
            </td>
          </tr>
        {% endif %}
      </tbody>
    </table>

    <div class="ex-totals">
      <table>
        <tr>
          <td class="k">Total Amount</td>
          <td class="v">{{ fmt_num(doc.total_amount) }}</td>
        </tr>
      </table>
    </div>

    <div class="ex-sign-row">
      <div class="ex-sign-box">
        <div class="ex-sign-line">Prepared By</div>
        <div class="ex-sign-meta">{{ prepared_name }}</div>
      </div>

      <div class="ex-sign-box">
        <div class="ex-sign-line">Reviewed By</div>
        <div class="ex-sign-meta">{{ expense_approver_name }}</div>
      </div>

      {% if finance_name %}
      <div class="ex-sign-box">
        <div class="ex-sign-line">Checked By</div>
        <div class="ex-sign-meta">{{ finance_name }}</div>
      </div>
      {% endif %}

      <div class="ex-sign-box">
        <div class="ex-sign-line">Approved By</div>
        <div class="ex-sign-meta">{{ director_name }}</div>
      </div>
    </div>

    <div class="ex-footer">
      This voucher is system generated. Signatures are required for audit compliance.
    </div>
  </div>
</div>
{% else %}
  <div style="padding:10px; border:1px solid #999; color:red;"><b>Document Should be Approved and then Submitted.</b></div>
{% endif %}
